function configure(multiplier){return G=>{
 let spellOwner=null;
 const strike=G.necromancerStrike,damage=G.damage;
 G.necromancerStrike=function(w,h,t,d){const old=spellOwner;spellOwner=h;try{return strike(w,h,t,d);}finally{spellOwner=old;}};
 G.damage=function(w,t,a,attacker){const magical=attacker?.classId==='mage'||attacker?.classId==='healer'||spellOwner&&attacker===spellOwner;return damage(w,t,a*(t?.type==='broodcap'&&magical?multiplier:1),attacker);};
};}
